"""Write complete V88/V89 public comparisons and release-status documentation."""
from pathlib import Path
from v57_pie import read,write,sha
ROOT=Path(__file__).resolve().parent

def report(version,folder,primary):
 a=ROOT/'experiments'/folder/'analysis';d=read(a/'release_decision.json');b=read(a/'mean_results.json');lines=[f'# V{version} measured results','',('**Upload-ready experimental candidate.**' if (a/'independent_validation.json').exists() and read(a/'independent_validation.json')['passed'] else '**Eligible for experimental generation; validation pending.**' if d['experimental_release_allowed'] else '**Rejected; no submission package generated.**'),'','The candidate is fixed by the prospectively recorded protocol. All public biology is reused, both technical seeds share donor biology, and no hidden score improvement is established. V66/V82 remains the best published reference until a new hosted result exists.','','## Broad public means','','655 target/context pairs with equal study votes. Lower profile error is favorable; higher raw PDS is favorable. These values are not anchored competition scores.','','| Arm | Profile error / V66 | Error reduction | PDS change |','|---|---:|---:|---:|']
 for arm,s in b['summary'].items():lines.append(f"| {arm} | {s['profile_ratio']:.9f} | {100*(1-s['profile_ratio']):.4f}% | {s['pds_change']:+.9f} |")
 lines+=['','Strong broad checks: '+', '.join(k+'='+str(v) for k,v in b['checks'].items())+'.','','## Paired integer-count results','','| Seed | Arm | Profile MSE | PDS | Fidelity | Reach | Jaccard | NMAE |','|---|---|---:|---:|---:|---:|---:|---:|']
 for offset in [0,620000]:
  c=read(a/f'count_assessment_{offset}.json')
  for arm,s in c['summary'].items():lines.append('| '+str(offset)+' | '+arm+' | '+' | '.join('missing' if s[k] is None else f'{s[k]:.9f}' for k in ['profile_MSE','pds','fidelity','reach','jaccard','nmae'])+' |')
 lines+=['','## Frozen decision','','- Strong support: '+str(d['strong_support'])+'.','- Bounded experimental release allowed: '+str(d['experimental_release_allowed'])+'.','- Broad safety checks: '+', '.join(k+'='+str(v) for k,v in d['broad_safety_checks'].items())+'.']
 for offset,r in d['seeds'].items():lines+=['- Seed '+offset+' experimental checks: '+', '.join(k+'='+str(v) for k,v in r['experimental_checks'].items())+'.','- Seed '+offset+' improved endpoints: '+', '.join(r['improved_endpoints'])+'.','- Seed '+offset+' strict checks: '+', '.join(k+'='+str(v) for k,v in r['strong_checks'].items())+'.']
 if version==88:lines+=['','The converged fit and numerical mixture intervals did not meet the overlap limits on either seed; first-seed PDS also failed. No control or alternative strength was promoted. V88 produced84 new populations plus28 reused baselines across its two seeds, with672 fresh tied-rank coordinates and224 previously checked baseline coordinates. Independent source, profile and count-statistic audits passed. Four production adapters were written in advance but were not run because release was blocked.']
 else:
  lines+=['','V89 releases the earlier V86 interval25 configuration; it is not a newly learned architecture. Public predictions and all56 first-seed records were adopted from V86, after exact hash checks. The second-seed test generated42 new populations and reused14 V84 baselines. The known first-seed donor result informed candidate selection, so the repeat test is technical verification on reused biology, not a blind clinical or biological confirmation.','', 'The stronger criteria still matter: the candidate did not establish superiority to all controls. The bounded experimental rule does not establish a private score gain. The V86 finite-iteration fit and normal-moment interval remain approximations; production source-model metadata reports actual iteration counts without claiming convergence.']
  if (a/'submission_ready.json').exists() and (a/'independent_validation.json').exists():
   ready=read(a/'submission_ready.json');audit=read(a/'independent_validation.json');assert audit['passed'];lines+=['','## Submission file','','`experiments/'+folder+'/prediction.vcc`','',f"- Bytes: {ready['bytes']:,}.",'- SHA256: `'+ready['sha256']+'`.','- Official prep and full independent payload comparison passed.','- Every one of360,000cells has the original selected control library total;12 complete groups regenerate exactly.','- Gene/context/target axes and400cells per group match the competition specification.','- Uploaded: false.','','CMD upload command:','','```cmd',f'.\\.competition_env\\Scripts\\python.exe -m vcc submit .\\experiments\\{folder}\\prediction.vcc -m "Conservative response projection v{version} experimental" --wait','```']
 lines+=['','Root code and compact evidence are versioned; large arrays, models, cells and packages remain local and ignored. See V'+str(version)+'_STRATEGY.md and the frozen JSON protocols for the full reproduction sequence.']
 (ROOT/f'V{version}_RESULTS.md').write_bytes(('\n'.join(lines)+'\n').encode('utf-8'))
if __name__=='__main__':
 report(88,'v88_mixture_quantiles','exact125')
 if (ROOT/'experiments/v89_v86_projection/analysis/release_decision.json').exists():report(89,'v89_v86_projection','interval25')
 print('V88/V89 measured result reports written',flush=True)
